"""Schema-driven BER encoder for the ASN.1 dissectors generated by asn2wrs.

The type tree is read from the generated dissector (packet-<proto>.c): the
ber_sequence_t / ber_choice_t tables and the dissect_<proto>_<Type>()
bodies.  encode() builds a valid BER encoding of any type.  The choice
alternatives are visited round robin, optional elements are included
pseudo randomly, so a few encodings of one type cover most of its tree.
Everything is synthetic; the values are made up.
"""
import re
import random

UNI = {'BOOLEAN': 1, 'INTEGER': 2, 'BIT_STRING': 3, 'OCTET_STRING': 4, 'NULL': 5,
       'OID': 6, 'ENUMERATED': 10, 'UTF8String': 12, 'SEQUENCE': 16, 'SET': 17,
       'NumericString': 18, 'PrintableString': 19, 'TeletexString': 20,
       'VideotexString': 21, 'IA5String': 22, 'UTCTime': 23, 'GeneralizedTime': 24,
       'GraphicString': 25, 'VisibleString': 26, 'GeneralString': 27}
CLS = {'BER_CLASS_UNI': 0, 'BER_CLASS_APP': 1, 'BER_CLASS_CON': 2, 'BER_CLASS_PRI': 3,
       'BER_CLASS_ANY': -1}


def ident(cls, tag, constructed):
    c = (cls << 6) | (0x20 if constructed else 0)
    if tag < 31:
        return bytes([c | tag])
    out = [tag & 0x7f]
    tag >>= 7
    while tag:
        out.insert(0, 0x80 | (tag & 0x7f))
        tag >>= 7
    return bytes([c | 31] + out)


def length(n):
    if n < 0x80:
        return bytes([n])
    if n < 0x100:
        return bytes([0x81, n])
    return bytes([0x82, n >> 8, n & 0xff])


def tlv(cls, tag, constructed, body):
    return ident(cls, tag, constructed) + length(len(body)) + body


class Schema:
    def __init__(self, path, prefix, seed=1):
        self.src = open(path).read()
        self.prefix = prefix
        self.rng = random.Random(seed)
        self.rr = {}
        self.funcs = {}
        self.tables = {}
        self.hooks = {}
        self.cur_hf = None
        self.fixed = {}      # func name -> bytes, for octet strings that need valid contents
        self.hftype = dict(re.findall(r'\{\s*&(hf_\w+),\s*\{\s*"[^"]*",\s*"[^"]*",\s*(FT_\w+)', self.src))
        self.depth = 0
        self.maxdepth = 7
        self._parse()
        self._scores()

    # ---- parsing
    def _num(self, s):
        s = s.strip()
        if s in UNI:
            return UNI[s]
        s = s.replace('BER_UNI_TAG_', '')
        if s in UNI:
            return UNI[s]
        try:
            return int(s, 0)
        except ValueError:
            return None

    def _parse(self):
        s = self.src
        for m in re.finditer(r'static const ber_(sequence|choice)_t (\w+)\[\d*\] = \{(.*?)\n\};', s, re.S):
            kind, name, body = m.groups()
            ents = []
            for e in re.finditer(r'\{\s*(?:(\d+)\s*,\s*)?(&\w+|NULL)\s*,\s*(BER_CLASS_\w+)(?:/\*choice\*/)?\s*,\s*([^,]+?)(?:/\*choice\*/)?\s*,\s*([^,]+?)\s*,\s*(\w+)\s*\}', body):
                val, hf, cls, tag, flags, func = e.groups()
                if func == 'NULL':
                    continue
                ents.append(dict(hf=hf[1:] if hf != 'NULL' else None, val=val, cls=CLS[cls], tag=self._num(tag) if self._num(tag) is not None else -1,
                                 flags=flags, func=func))
            self.tables[name] = (kind, ents)
        pat = r'(?:^|\n)(?:static )?unsigned\n(dissect_%s_\w+)\(bool implicit_tag.*?\) \{\n(.*?)\n\}\n' % self.prefix
        for m in re.finditer(pat, s, re.S):
            name, body = m.groups()
            self.funcs[name] = self._kind(name, body)

    def _args(self, call):
        # split the arguments of "name(a, b, c)" at top level commas
        i = call.index('(')
        a, depth, cur = [], 0, ''
        for ch in call[i + 1:]:
            if ch == '(':
                depth += 1
            if ch == ')':
                if depth == 0:
                    break
                depth -= 1
            if ch == ',' and depth == 0:
                a.append(cur.strip()); cur = ''
            else:
                cur += ch
        a.append(cur.strip())
        return a

    def _kind(self, name, body):
        m = re.search(r'(dissect_ber_\w+|dissect_%s_\w+)\((.*?)\);' % self.prefix, body, re.S)
        if not m:
            return ('any',)
        fn = m.group(1)
        call = fn + '(' + m.group(2) + ')'
        a = self._args(call)
        if fn.startswith('dissect_%s_' % self.prefix):
            return ('alias', fn)
        # remove custom hooks (functions with their own handwritten body)
        if fn in ('dissect_ber_sequence', 'dissect_ber_set'):
            return ('seq' if fn.endswith('sequence') else 'set', a[5])
        if fn in ('dissect_ber_sequence_of', 'dissect_ber_set_of'):
            return ('seqof' if 'sequence' in fn else 'setof', a[5], 0, 0)
        if fn in ('dissect_ber_constrained_sequence_of', 'dissect_ber_constrained_set_of'):
            return ('seqof' if 'sequence' in fn else 'setof', a[7], self._num(a[5]) or 0, self._num(a[6]) or 0)
        if fn == 'dissect_ber_choice':
            return ('choice', a[4])
        if fn == 'dissect_ber_integer':
            return ('int', None, None)
        if fn == 'dissect_ber_constrained_integer':
            return ('int', self._num(a[5]), self._num(a[6]))
        if fn == 'dissect_ber_boolean':
            return ('bool',)
        if fn == 'dissect_ber_null':
            return ('null',)
        if fn == 'dissect_ber_octet_string':
            return ('octets', 0, 0)
        if fn == 'dissect_ber_constrained_octet_string':
            return ('octets', self._num(a[5]) or 0, self._num(a[6]) or 0)
        if fn in ('dissect_ber_object_identifier', 'dissect_ber_object_identifier_str'):
            return ('oid',)
        if fn == 'dissect_ber_restricted_string':
            return ('str', self._num(a[1].replace('BER_UNI_TAG_', '')) or 19, 0, 0)
        if fn == 'dissect_ber_constrained_restricted_string':
            return ('str', self._num(a[1].replace('BER_UNI_TAG_', '')) or 19, self._num(a[6]) or 0, self._num(a[7]) or 0)
        if fn == 'dissect_ber_tagged_type':
            return ('tagged', CLS.get(a[6], 2), self._num(a[7]), a[8] == 'true', a[9])
        return ('any',)

    # ---- minimal size, used to leave recursive types
    def _scores(self):
        INF = 10 ** 9
        sc = {f: INF for f in self.funcs}

        def ent_sc(e):
            return sc.get(e['func'], 1)
        for _ in range(60):
            ch = False
            for f, k in self.funcs.items():
                t = k[0]
                if t in ('seq', 'set'):
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + sum(ent_sc(e) for e in ents if 'OPTIONAL' not in e['flags'])
                elif t in ('seqof', 'setof'):
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + (ent_sc(ents[0]) if k[2] > 0 and ents else 0)
                elif t == 'choice':
                    ents = self.tables.get(k[1], ('', []))[1]
                    v = 1 + min([ent_sc(e) for e in ents] or [0])
                elif t == 'alias':
                    v = sc.get(k[1], 1)
                elif t == 'tagged':
                    v = 1 + sc.get(k[4], 1)
                else:
                    v = 1
                v = min(v, INF)
                if v < sc[f]:
                    sc[f] = v; ch = True
            if not ch:
                break
        self.score = sc

    def reach_max(self, func, seen=None):
        """largest number of alternatives of any CHOICE reachable from func"""
        seen = set() if seen is None else seen
        if func in seen or func not in self.funcs:
            return 0
        seen.add(func)
        k = self.funcs[func]
        best = 0
        if k[0] == 'alias':
            return self.reach_max(k[1], seen)
        if k[0] == 'tagged':
            return self.reach_max(k[4], seen)
        if k[0] in ('seq', 'set', 'seqof', 'setof', 'choice'):
            ents = self.tables.get(k[1], ('', []))[1]
            if k[0] == 'choice':
                best = len(ents)
            for e in ents:
                best = max(best, self.reach_max(e['func'], seen))
        return best

    # ---- encoding
    def pick(self, key, n):
        i = self.rr.get(key, self.rng.randrange(n))
        self.rr[key] = (i + 1) % n
        return i

    def enc(self, func, ov=None):
        """Encode type `func` (dissect_ function name). ov = (class, tag)
        replaces the type's own tag (IMPLICIT tagging)."""
        if func in self.hooks:
            return self.hooks[func](self, ov)
        k = self.funcs.get(func, ('any',))
        t = k[0]
        deep = self.depth > self.maxdepth
        self.depth += 1
        try:
            return self._enc(func, k, t, ov, deep)
        finally:
            self.depth -= 1

    def _wrap(self, ov, ucls_tag, constructed, body):
        cls, tag = ov if ov else (0, ucls_tag)
        return tlv(cls, tag, constructed, body)

    def resolve(self, func):
        while func in self.funcs and self.funcs[func][0] == 'alias':
            func = self.funcs[func][1]
        return self.funcs.get(func, ('any',))[0]

    def _entry(self, e, deep=False):
        old = self.cur_hf
        self.cur_hf = e.get('hf')
        try:
            return self._entry1(e, deep)
        finally:
            self.cur_hf = old

    def _entry1(self, e, deep=False):
        if e['cls'] == 0 and e['tag'] >= 0:
            return self.enc(e['func'], (0, e['tag']))
        if e['cls'] in (0, -1) or 'NOOWNTAG' in e['flags']:
            return self.enc(e['func'], None)
        if 'IMPLTAG' in e['flags'] and self.resolve(e['func']) == 'choice':
            # a tag on a CHOICE is explicit
            return tlv(e['cls'], e['tag'], True, self.enc(e['func'], None))
        if 'IMPLTAG' in e['flags']:
            return self.enc(e['func'], (e['cls'], e['tag']))
        return tlv(e['cls'], e['tag'], True, self.enc(e['func'], None))

    def _enc(self, func, k, t, ov, deep):
        rng = self.rng
        if t == 'alias':
            return self.enc(k[1], ov)
        if t in ('seq', 'set'):
            ents = self.tables[k[1]][1]
            body = b''
            for e in ents:
                if 'OPTIONAL' in e['flags'] and (deep or rng.random() < 0.3):
                    continue
                body += self._entry(e)
            return self._wrap(ov, 16 if t == 'seq' else 17, True, body)
        if t in ('seqof', 'setof'):
            ents = self.tables[k[1]][1]
            lo, hi = k[2], k[3]
            n = max(lo, 1) if deep else rng.choice([1, 2, 2, 3])
            if hi:
                n = min(n, hi)
            body = b''.join(self._entry(ents[0]) for _ in range(n))
            return self._wrap(ov, 16 if t == 'seqof' else 17, True, body)
        if t == 'choice':
            ents = self.tables[k[1]][1]
            if deep:
                i = min(range(len(ents)), key=lambda j: self.score.get(ents[j]['func'], 1))
            else:
                i = self.pick(k[1], len(ents))
            return self._entry(ents[i])
        if t == 'int':
            lo, hi = k[1], k[2]
            if lo is None:
                v = rng.choice([0, 1, 2, 3, 5, 7, 100, 255, 256, 1000, 70000])
            else:
                if hi is None or hi < lo:
                    hi = lo + 10
                span = min(hi, lo + 300)
                v = rng.choice([lo, hi if hi < 2 ** 31 else lo, lo + (span - lo) // 2, rng.randint(lo, span)])
            n = 1
            while not (-(1 << (8 * n - 1)) <= v < (1 << (8 * n - 1))):
                n += 1
            return self._wrap(ov, 2, False, v.to_bytes(n, 'big', signed=True))
        if t == 'bool':
            return self._wrap(ov, 1, False, bytes([rng.choice([0, 0xff])]))
        if t == 'null':
            return self._wrap(ov, 5, False, b'')
        if t == 'octets' and func in self.fixed:
            v = self.fixed[func]
            if callable(v):
                v = v(self)
            return self._wrap(ov, 4, False, v)
        if t == 'octets':
            lo, hi = k[1], k[2]
            n = rng.choice([1, 2, 3, 4, 5, 8, 9])
            ft = self.hftype.get(self.cur_hf)
            if ft in ('FT_UINT8', 'FT_INT8'): lo = hi = 1
            elif ft in ('FT_UINT16', 'FT_INT16'): lo = hi = 2
            elif ft in ('FT_UINT24', 'FT_INT24'): lo = hi = 3
            elif ft in ('FT_UINT32', 'FT_INT32'): lo = hi = 4
            if lo and n < lo: n = lo
            if hi and n > hi: n = hi
            return self._wrap(ov, 4, False, bytes(rng.randrange(256) for _ in range(n)))
        if t == 'oid':
            return self._wrap(ov, 6, False, bytes([0x2a, 0x03, rng.randrange(1, 100)]))
        if t == 'str':
            tag, lo, hi = k[1], k[2], k[3]
            n = rng.choice([1, 3, 6, 10])
            if lo and n < lo: n = lo
            if hi and n > hi: n = hi
            alpha = b'0123456789' if tag == 18 else b'ABCDEFGHabcdefgh01234'
            return self._wrap(ov, tag, False, bytes(rng.choice(alpha) for _ in range(n)))
        if t == 'tagged':
            cls, tag, explicit, inner = k[1], k[2], k[3], k[4]
            if ov:
                cls, tag = ov
            return tlv(cls, tag, True, self.enc(inner, None))
        # unknown (types of other dissectors): an empty SEQUENCE
        return self._wrap(ov, 16, True, b'')


if __name__ == '__main__':
    import sys, collections
    s = Schema(sys.argv[1], sys.argv[2])
    print(collections.Counter(k[0] for k in s.funcs.values()))
    print([f for f, k in s.funcs.items() if k[0] == 'any'])
